const rtdal010050Source0001 = "cran_pkg_dates = function(full = FALSE, maintainer = 'Yihui Xie') {\n  info = tools::CRAN_package_db()\n  pkgs = info[grep(maintainer, info$Maintainer), 'Package']\n  info = setNames(vector('list', length(pkgs)), pkgs)\n  for (p in pkgs) {\n    message('Processing ', p)\n    x = readLines(u <- sprintf('https://cran.rstudio.com/web/packages/%s/', p))\n    i = which(x == '<td>Published:</td>')\n    if (length(i) == 0) stop('Cannot find the publishing date from ', u)\n    d = as.Date(gsub('</?td>', '', x[i[1] + 1]))\n    x = try_silent(suppressWarnings(readLines(\n      u <- sprintf('https://cran.r-project.org/src/contrib/Archive/%s/', p)\n    )))\n    if (inherits(x, 'try-error')) {\n      info[[p]] = d; next\n    }\n    r = '.+</td><td align=\"right\">(\\\\d{4,}-\\\\d{2}-\\\\d{2}) .+'\n    d = c(d, as.Date(gsub(r, '\\\\1', grep(r, x, value = TRUE))))\n    info[[p]] = sort(d, decreasing = TRUE)\n  }\n  if (full) info else sort(do.call(c, lapply(info, `[`, 1)), decreasing = TRUE)\n}"

const rtdal010050Source0002 = `cran_updatable = function(days = 90, maintainer = 'Yihui Xie') {
  info = cran_pkg_dates(TRUE, maintainer)
  flag = unlist(lapply(info, function(d) {
    sum(d > Sys.Date() - 180) < 6 && d[1] < Sys.Date() - days
  }))
  if (length(pkgs <- names(which(flag))) == 0) return(pkgs)
  # look into DESCRIPTION in GitHub repos and see if new version has been pushed
  info = tools::CRAN_package_db()
  info = info[info$Package %in% pkgs, , drop = FALSE]
  pkgs = info$Package
  for (i in seq_len(nrow(info))) {
    b = grep_sub('^(https://github.com/[^/]+/[^/]+)/issues$', '\\1', info$BugReports[i])
    if (length(b) != 1) next
    f = tempfile()
    u = paste0(b, '/raw/HEAD/DESCRIPTION')
    if (is.null(tryCatch(download.file(u, f, quiet = TRUE), error = function(e) NULL))) next
    d = read.dcf(f)
    file.remove(f)
    if (!'Version' %in% colnames(d)) next
    if (as.numeric_version(d[, 'Version']) <= paste0(info$Version[i], '.1')) {
      pkgs = setdiff(pkgs, info$Package[i])
      message('Skipped package ', info$Package[i], ' ', d[, 'Version'], ' (no new version).')
    } else {
      message('Package can be updated: ', b)
    }
  }
  pkgs
}`

const rtdal010050Source0006 = `check_old_package = function(name, version) {
  if (is.na(pkg <- check_package_name()) || !(pkg %in% name)) return(FALSE)
  tryCatch(packageVersion(pkg) <= version[pkg == name], error = function(e) FALSE)
}`

