const rtdal010056Source0001 = `read_utf8 = function(con, error = FALSE, binary = FALSE) {
  # Reading via a binary connection avoids readLines() treating a Ctrl+Z byte
  # (\x1a) as end-of-file on Windows (see the 'binary' argument documentation).
  f = if (is.character(con)) con  # remember the file path for the message below
  if (is.character(con) && binary) {
    con = file(con, 'rb', encoding = 'UTF-8'); on.exit(close(con), add = TRUE)
  }
  # users may have set options(encoding = 'UTF-8'), which usually won't help but
  # will bring more trouble than good, so we reset this option temporarily
  opts = options(encoding = 'native.enc'); on.exit(options(opts), add = TRUE)
  x = readLines(con, encoding = 'UTF-8', warn = FALSE)
  i = invalid_utf8(x)
  n = length(i)
  if (n > 0) (if (error) stop else warning)(
    if (!is.null(f)) c('The file ', f, ' is not encoded in UTF-8. '),
    'These lines contain invalid UTF-8 characters: ',
    paste(c(head(i), if (n > 6) '...'), collapse = ', ')
  )
  x
}`

const rtdal010056Source0002 = `write_utf8 = function(text, con, ...) {
  if (is.null(text)) text = character(0)
  if (identical(con, '')) {
    cat(text, sep = '\n', file = con)
  } else {
    # prevent re-encoding the text in the file() connection in writeLines()
    # https://kevinushey.github.io/blog/2018/02/21/string-encoding-and-r/
    opts = options(encoding = 'native.enc'); on.exit(options(opts), add = TRUE)
    writeLines(enc2utf8(text), con, ..., useBytes = TRUE)
  }
  invisible(con)
}`

const rtdal010056Source0003 = `append_utf8 = function(text, con, sort = TRUE) {
  x = read_utf8(con, error = TRUE)
  x = c(x, text)
  if (is.logical(sort)) sort = if (sort) base::sort else identity
  if (is.function(sort)) x = sort(x)
  write_utf8(x, con)
}`

const rtdal010056Source0004 = `append_unique = function(text, con, sort = function(x) base::sort(unique(x))) {
  append_utf8(text, con, sort)
}`

const rtdal010056Source0009 = `read_bin = function(file, what = 'raw', n = file.info(file)$size, ...) {
  readBin(file, what, n, ...)
}`

const rtdal010056Source0010 = `read_all = function(files, before = function(f, x) NULL, after = function(f, x) NULL) {
  call_fun = function(fun, x, ...) {
    if (is.function(fun)) {
      if (length(formals(fun)) > 1) fun(x, ...) else fun(x)
    } else fun
  }
  x = unlist(lapply(files, function(f) {
    t = read_utf8(f)
    c(call_fun(before, f, t), t, call_fun(after, f, t))
  }))
  raw_string(x)
}`

const rtdal010056Source0011 = `process_file = function(file, fun = identity, x = read_utf8(file)) {
  x2 = fun(x)
  if (missing(file)) x2 else {
    if ((length(x2) != length(x)) || !all(x2 == x)) write_utf8(x2, file)
  }
}`

const rtdal010056Source0012 = `sort_file = function(..., fun = sort) {
  process_file(fun = fun, ...)
}`

const rtdal010056Source0013 = `gsub_file = function(file, ..., rw_error = TRUE) {
  if (!(file.access(file, 2) == 0 && file.access(file, 4) == 0)) {
    (if (rw_error) stop else warning)('Unable to read or write to ', file)
    if (!rw_error) return(invisible())
  }
  x1 = tryCatch(read_utf8(file, error = TRUE), error = function(e) if (rw_error) stop(e))
  if (is.null(x1)) return(invisible())
  x2 = gsub(x = x1, ...)
  if (!identical(x1, x2)) write_utf8(x2, file)
}`

const rtdal010056Source0014 = `gsub_files = function(files, ...) {
  for (f in files) gsub_file(f, ...)
}`

const rtdal010056Source0015 = `gsub_dir = function(..., dir = '.', recursive = TRUE, ext = NULL, mimetype = '.*') {
  files = list.files(dir, full.names = TRUE, recursive = recursive)
  if (length(ext)) files = files[file_ext(files) %in% ext]
  if (mimetype != '.*') files = files[grep(mimetype, mime_type(files))]
  gsub_files(files, ...)
}`

const rtdal010056Source0016 = `gsub_ext = function(ext, ..., dir = '.', recursive = TRUE) {
  gsub_dir(..., dir = dir, recursive = recursive, ext = ext)
}`

const rtdal010056Source0017 = `grep_sub = function(pattern, replacement, x, ...) {
  x = grep(pattern, x, value = TRUE, ...)
  gsub(pattern, replacement, x, ...)
}`

const rtdal010056Source0018 = `download_file = function(
  url, output = url_filename(url), ...,
  .error = 'No download method works (auto/wininet/wget/curl/lynx)'
) {
  if (getOption('timeout') == 60L) {
    opts = options(timeout = 3600)  # one hour
    on.exit(options(opts), add = TRUE)
  }
  dir_create(dirname(output))
  download = function(method = 'auto') suppressWarnings({
    # curl needs to add a -L option to follow redirects
    if (method == 'curl' && is.null(getOption('download.file.extra'))) {
      opts2 = options(download.file.extra = c('-L', '--fail'))
      on.exit(options(opts2), add = TRUE)
    }
    tryCatch(download.file(url, output, ..., method = method), error = function(e) 1L)
  })
  for (method in c('libcurl', 'auto', if (is_windows()) 'wininet')) {
    if (download(method) == 0) return(output)
  }
  # check for libcurl/curl/wget/lynx, call download.file with appropriate method
  for (method in c('curl', 'wget', 'lynx')) {
    if (Sys.which(method) != '' && download(method) == 0) return(output)
  }
  stop(.error)
}`

const rtdal010056Source0019 = `url_accessible = function(x, use_curl = !capabilities('libcurl'), ...) {
  try_status = function(code) tryCatch(code < 400, error = function(e) FALSE)
  if (use_curl) {
    h = curl::new_handle()
    curl::handle_setopt(h, customrequest = 'HEAD', nobody = TRUE)
    try_status(curl::curl_fetch_memory(x, h)$status_code)
  } else {
    # use curlGetHeaders() instead
    try_status(attr2(curlGetHeaders(x, ...), 'status'))
  }
}`

const rtdal010056Source0021 = `.url_destination = local({
  db = list()
  function(x, force = FALSE) {
    if (!force && is.character(db[[x]])) return(db[[x]])
    h = curlGetHeaders(x)
    if ((s <- attr2(h, 'status')) >= 400) stop2('URL ', x, ' returned status code ', s)
    u = grep_sub('^location:\\s+(.+?)[\r\n]*$', '\\1', h, ignore.case = TRUE)
    db[[x]] <<- if (length(u)) tail(u, 1) else x
  }
})`

const rtdal010056Source0022 = `msg_cat = function(...) {
  x = paste(c(...), collapse = '')
  withRestarts({
    signalCondition(simpleMessage(x))
    cat(x)
  }, muffleMessage = function() invisible(NULL))
}`

const rtdal010056Source0023 = `lazy_save = function(list = NULL, path = './', method = 'auto', envir = parent.frame()) {
  m = io_method(method, path)
  idx = lazy_idx(path, m$name)
  m$save(list, idx)
  for (i in seq_along(list)) {
    v = get(list[[i]], envir, inherits = FALSE)
    m$save(v, sprintf('%s%d.%s', path, i, m$name))
  }
}`

const rtdal010056Source0024 = `lazy_load = function(path = './', method = 'auto', envir = parent.frame()) {
  m = io_method(method, path)
  idx = lazy_idx(path, m$name)
  vars = m$load(idx)
  .mapply(function(path, name) {
    delayedAssign(name, m$load(path), assign.env = envir)
  }, list(sprintf('%s%d.%s', path, seq_along(vars), m$name), vars), NULL)
  invisible(vars)
}`

