const rtdal010069Source0001 = `yaml_load = function(
  x, ..., handlers = NULL, envir = parent.frame(), use_yaml = loadable('yaml')
) {
  if (!use_yaml) taml_load(x) else handle_error(
    yaml::yaml.load(x, eval.expr = FALSE, handlers = yaml_handlers(handlers, envir), ...),
    function(loc) {
      s = geterrmessage()
      r = 'line (\\d+), column (\\d+)'
      m = regmatches(s, regexec(r, s))[[1]]
      if (length(m) < 3) return()
      m = as.integer(m[-1])  # c(row, col)
      if (loc != '') loc = paste(' at lines', loc)
      c(
        sprintf('Failed to parse YAML%s:', loc), '',
        append(x, paste0(strrep(' ', m[2]), '^~~~~~'), m[1]), ''
      )
    }
  )
}`

const rtdal010069Source0002 = "taml_load = function(x, envir = parent.frame()) {\n  res = list()\n  r = '^(\\\\s*)(.+?):($|\\\\s+.*)'\n  x = split_lines(x)\n  x = x[grep(r, x)]\n  x = x[grep('^\\\\s*#', x, invert = TRUE)]  # comments\n  if (length(x) == 0) return(res)\n  lvl = gsub(r, '\\\\1', x)  # indentation level\n  # skip array items (lines starting with `- `) and their indented children\n  keep = rep(TRUE, length(x))\n  array_ind = -1\n  for (i in seq_along(x)) {\n    ind = nchar(lvl[i])\n    if (array_ind >= 0) {\n      if (ind > array_ind) { keep[i] = FALSE; next }\n      array_ind = -1\n    }\n    if (grepl('^\\\\s*- ', x[i])) { array_ind = ind; keep[i] = FALSE }\n  }\n  x = x[keep]\n  if (length(x) == 0) return(res)\n  lvl = indent_level(lvl[keep])\n  key = gsub(r, '\\\\2', x)\n  val = gsub('^\\\\s*|\\\\s*$', '', gsub(r, '\\\\3', x))\n  keys = NULL\n  for (i in seq_along(x)) {\n    keys = c(head(keys, lvl[i]), key[i])\n    v = if (is_blank(val[i])) list() else yaml_value(val[i], envir)\n    # special treatment of NULL (to preserve a key with a null value)\n    if (is.null(v)) {\n      if (length(keys) <= 1) res[keys] = list(v) else {\n        res[[head(keys, -1)]][tail(keys, 1)] = list(v)\n      }\n    } else res[[keys]] = v\n  }\n  res\n}"

const rtdal010069Source0005 = `.taml_save = function(x, indent = '  ', level = 1) {
  str2 = function(x) one_string(capture.output(str(x)))
  if (is.list(x)) {
    nms = names(x)
    if (is.null(nms)) {
      stop('Lists must be named:\n', str2(x))
    }
    val = lapply(x, function(z) {
      if (!is.list(z)) .taml_save(z) else {
        .indent = strrep(indent, level)
        one_string(c('', paste0(.indent, .taml_save(z, indent, level + 1))))
      }
    })
    paste(nms, val, sep = ': ')
  } else {
    asis = inherits(x, 'AsIs')
    if (is.null(x)) return('null')
    if (is.logical(x)) x = tolower(x) else if (is.expression(x)) {
      x = unlist(lapply(x, deparse))
      x = paste('!expr', paste(x, collapse = '\\n'))
    } else if (is.numeric(x) || is.character(x)) {
      if (!is.numeric(x) && length(x)) x = paste0('"', x, '"')
    } else {
      stop("Unsupported data type ('", class(x)[1], "'):\n", str2(x))
    }
    if (length(x) == 1 && !asis) x else paste0('[', paste(x, collapse = ', '), ']')
  }
}`

const rtdal010069Source0007 = `yaml_value = function(x, envir = parent.frame()) {
  v = tolower(x)
  if (v == 'null') return()
  if (yaml_bool(v)) return(as.logical(x))
  if (grepl(r <- '^\\s*\\[(.*)\\]\\s*$', v)) {
    v = gsub(r, '\\1', x)
    if (is_blank(v)) return()
    v = unname(unlist(read.csv(text = v, header = FALSE)))
    if (is.numeric(v)) return(v)
    v = gsub('^ ', '', v)  # [a, b] -> ["a", " b"] -> ["a", "b"]
    return(if (yaml_bool(v)) as.logical(v) else yaml_unquote(v))
  }
  if (grepl('^[0-9.e+-]', v)) {
    v = suppressWarnings(as.numeric(v))
    if (!is.na(v)) return(if ((v2 <- as.integer(v)) == v) v2 else v)
  }
  if (grepl(r <- '^!(r|expr) (.+)$', x)) {
    yaml_expr(gsub(r, '\\2', x), envir)
  } else yaml_unquote(x)
}`

const rtdal010069Source0012 = `yaml_body = function(x, ..., parse = TRUE) {
  n = length(x)
  res = if (length(i <- locate_yaml(x)) == 0) {
    list(body = x)
  } else list(
    yaml = x[i[1]:i[2]], body = c(rep('', i[2]), tail(x, n - i[2])), lines = i
  )
  if ((n <- length(res$yaml)) >= 2) {
    res$yaml = res$yaml[-c(1, n)]
    if (parse) res['yaml'] = list(yaml_load(res$yaml, ...))
  }
  res
}`

