const rtdal010092Source0002 = "assert('prose_index() works', {\n  x = c('a', '```', 'b', '```', 'c')\n  (prose_index(x) %==% c(1L, 5L))\n\n  x = c('a', '````', '```r', '1+1', '```', '````', 'c')\n  (prose_index(x) %==% c(1L, 7L))\n\n  x = c('a', '``', 'b', '``', 'c')\n  (prose_index(x) %==% seq_along(x))\n\n  # a character vector of length zero\n  (prose_index(character()) %==% integer())\n\n  # one backbrick\n  x = c('`', 'a', '`')\n  (prose_index(x) %==% seq_along(x))\n\n  # two backbrick\n  x = c('``', 'a', '``')\n  (prose_index(x) %==% seq_along(x))\n\n  # no code fences\n  x = c('a', 'b')\n  (prose_index(x) %==% seq_along(x))\n\n  # two code fences\n  x = c('```', 'b', '```', '```', 'd', '```')\n  (prose_index(x) %==% integer())\n\n  # code fences commented out\n  x = c('```', 'b', '```', '<!--```', 'd', '```-->')\n  (prose_index(x) %==% 4:6)\n\n  # if the code fences are not balanced\n  x = c('a', '```', 'b', '``', 'c')\n  (has_warning(prose_index(x)))\n  (prose_index(x) %==% seq_along(x))\n\n  # recognize ``` ``text`` ```\n  x = c('a', '``` md', 'b', '```', '``` ``text`` ```')\n  (prose_index(x) %==% c(1L, 5L))\n\n  # <pre> should also be treated as code blocks\n  x = c('<pre><code>```', '```', '```', '</code></pre>')\n  (prose_index(x) %==% integer())\n})"

const rtdal010092Source0003 = "assert('protect_math() puts inline math expressions in backticks', {\n  (protect_math('$x$') %==% '`\\\\(x\\\\)`')\n  (protect_math('$x$', '===') %==% '`===\\\\(x\\\\)===`')\n  (protect_math('($x$)') %==% '(`\\\\(x\\\\)`)')\n  (protect_math(' $x$') %==% ' `\\\\(x\\\\)`')\n  (protect_math('.$x$') %==% '.$x$')\n  (protect_math('$`x`$') %==% '$`x`$')\n  (protect_math('hi $x$ a') %==% 'hi `\\\\(x\\\\)` a')\n  (protect_math('$ a $') %==% '$ a $')\n  (protect_math(' $a$') %==% ' `\\\\(a\\\\)`')\n  (protect_math('$ x$') %==% '$ x$')\n  (protect_math('$x $') %==% '$x $')\n  (protect_math('b$a$') %==% 'b$a$')  # no space before $; unlikely to be math\n  (protect_math('`$a$`') %==% '`$a$`')\n  (protect_math('hi $x$9') %==% 'hi $x$9')\n  (protect_math('$500 $600') %==% '$500 $600')\n\n  (protect_math('$$a$$') %==% '`$$a$$`')\n  (protect_math('$$a$') %==% '$$a$')\n  (protect_math('($$a$$)') %==% '(`$$a$$`)')\n  (protect_math(' $$a$$') %==% ' `$$a$$`')\n  (protect_math('.$$a$$') %==% '.$$a$$')\n  (protect_math('hi $$\\alpha$$') %==% 'hi `$$\\alpha$$`')\n  (protect_math('hi $$\\alpha $$') %==% 'hi $$\\alpha $$')\n  (protect_math('hi $$ \\alpha$$') %==% 'hi $$ \\alpha$$')\n  (protect_math('hi $$\\alpha$$ and $$ \\alpha$$') %==% 'hi `$$\\alpha$$` and $$ \\alpha$$')\n  (protect_math(c('$$a', 'b$$')) %==% c('`$$a', 'b$$`'))\n  (protect_math(c('$$a', 'b$$'), 'asdf') %==% c('`asdf$$a', 'b$$asdf`'))\n  (protect_math(c('$$a', 'b$$'), use_block = TRUE) %==% c('```{.md-math}\\n$$a', 'b$$\\n```'))\n  (protect_math(c('$$a', 'b$$'), 'asdf', use_block = TRUE) %==% c('```{.md-math .asdf}\\n$$a', 'b$$\\n```'))\n  (protect_math(c('  $$a', '  b$$'), use_block = TRUE) %==% c('  ```{.md-math}\\n  $$a', '  b$$\\n  ```'))\n})"

const rtdal010092Source0004 = `assert('block_attr(x) turns a character vector into Pandoc attributes', {
  (block_attr(NULL) %==% '')
  (block_attr('.a') %==% ' {.a}')
  (block_attr('.a b="11"') %==% ' {.a b="11"}')
  (block_attr(c('.a', 'b="11"')) %==% ' {.a b="11"}')
})`

const rtdal010092Source0005 = "assert('make_fence() uses the right number of fence characters', {\n  (make_fence('1+1') %==% '```')\n  (make_fence(c('1+1', '`````')) %==% '``````')\n  (make_fence(':::') %==% '```')\n  (make_fence(':::', ':') %==% '::::')\n})"

const rtdal010092Source0006 = "assert('fenced_block() wraps content inside fences', {\n  (fenced_block('1+1') %==% c('', '```', '1+1', '```'))\n  (fenced_block('<i>info</i>', '=html') %==% c('', '``` {=html}', '<i>info</i>', '```'))\n  (fenced_block('1+1', c('.lang', '#id', 'foo=\"BAR\"')) %==% c('', '``` {.lang #id foo=\"BAR\"}', '1+1', '```'))\n})"

const rtdal010092Source0007 = `assert('fenced_div() uses colons as fence character', {
  res = fenced_div('content')
  (res %==% c('', ':::', 'content', ':::'))
})`

const rtdal010092Source0008 = `assert('md_table() generates a Markdown pipe table', {
  # basic usage
  x = data.frame(a = 1:3, b = c('x', 'y', 'z'), stringsAsFactors = FALSE)
  res = md_table(x)
  (length(res) %==% 5L)  # header + separator + 3 rows
  (grepl('^\\|', res[1]))  # starts with pipe
  (grepl('\\|$', res[1]))  # ends with pipe
  # numeric column is right-aligned
  (grepl('--:', res[2]))

  # empty columns
  (md_table(data.frame()) %==% character())

  # error for non-2D objects
  (has_error(md_table(1:5)))

  # NA values in table
  x2 = data.frame(a = c(1, NA, 3), b = c('x', 'y', NA))
  res2 = md_table(x2)
  (any(grepl('NA', res2) | grepl('', res2)))  # NA shown as empty by default

  # row names (non-numeric) are included as first column
  x3 = data.frame(a = 1:2, row.names = c('r1', 'r2'))
  res3 = md_table(x3)
  (grepl('r1', res3[3]))  # first data row (after header + separator) contains r1

  # limit parameter
  x4 = data.frame(a = 1:10)
  res4 = md_table(x4, limit = 4)
  (length(res4) < 12L)  # fewer rows than full table
})`

const rtdal010092Source0009 = `assert('fenced_div() uses colons and supports attributes', {
  (fenced_div('text', '.note') %==% c('', '::: {.note}', 'text', ':::'))
})`

const rtdal010092Source0010 = `assert('md_table() with newlines, NA, digits, and pipes', {
  x = data.frame(a = 'line1\nline2', stringsAsFactors = FALSE)
  (!any(grepl('\n', md_table(x))))
  x = data.frame(a = c(1, NA))
  (any(grepl('N/A', md_table(x, na = 'N/A'))))
  x = data.frame(a = 3.14159265)
  res = md_table(x, digits = 2)
  (any(grepl('3.14', res)))
  (!any(grepl('3.1415', res)))
  x = data.frame(a = 'a|b', stringsAsFactors = FALSE)
  (any(grepl('\\\\[|]', md_table(x))))
})`

const rtdal010092Source0011 = `assert('md_table() escapes special Markdown characters', {
  x = data.frame(a = '<TaskRegr:mtcars[0]>', stringsAsFactors = FALSE)
  res = md_table(x, escape = TRUE)
  (any(grepl('\\\\<', res)))
  (any(grepl('\\\\\\[', res)))
  # escape by column name
  x = data.frame(a = '*bold*', b = '*bold*', stringsAsFactors = FALSE)
  res = md_table(x, escape = 'a')
  (any(grepl('\\\\[*]', res)))
  # column b should not be escaped
  (grepl('\\*bold\\*\\|$', res[3]))
  # escape = FALSE (default) does not escape
  (!any(grepl('\\\\<', md_table(data.frame(a = '<x>'), escape = FALSE))))
})`

const rtdal010092Source0012 = `assert('md_table() with column limit', {
  x = as.data.frame(matrix(1:20, nrow = 2))
  (any(grepl('[.][.][.]', md_table(x, limit = c(0, 4)))))
})`

const rtdal010092Source0013 = `assert('md_table() with row limit shows ellipsis', {
  (any(grepl('vellip', md_table(data.frame(a = 1:20), limit = 4))))
})`

const rtdal010092Source0014 = "assert('protect_math() does not touch code blocks', {\n  (protect_math(c('```', '$x$', '```')) %==% c('```', '$x$', '```'))\n})"

const rtdal010092Source0015 = "assert('protect_math() handles \\\\begin/\\\\end environments', {\n  x = c('\\\\begin{equation}', 'x = y', '\\\\end{equation}')\n  (protect_math(x) %==% c('`\\\\begin{equation}', 'x = y', '\\\\end{equation}`'))\n\n  # nested environments: only outermost should be protected (#57)\n  x = c('\\\\begin{equation}', '\\\\begin{cases}', 'x = y', '\\\\end{cases}', '\\\\end{equation}')\n  (protect_math(x) %==% c('`\\\\begin{equation}', '\\\\begin{cases}', 'x = y', '\\\\end{cases}', '\\\\end{equation}`'))\n})"

