const rtdal010156Source0007 = `setMethod("getEncodingREnum", "character",
           function(doc, ...) {
             if(length(doc) == 0 || is.na(doc))
               return(CE_NATIVE)
             
             str = tolower(doc)
             if(any(str == c("utf8", "utf-8")))
                 CE_UTF8
             else if(any(str == c("latin1", "iso-8859-1")))
                 CE_LATIN1
             else
                 CE_NATIVE # or NA?
           })`

